        if resources:
            return move_towards(min(resources, key=lambda t: abs(t[0]-sx)+abs(t[1]-sy)))
        # default move towards opponent or stay
        dx = 0
        dy = 0
        if ox != sx:
            dx = 1 if ox > sx else -1
        if oy != sy:
